"""Convert between integers 1..3999 and canonical upper-case Roman numerals such as "MCMXCIV"."""
import re

_NUMERALS = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]
_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def to_roman(n):
    """Standard upper-case numeral for n, which must be an integer from 1 to 3999."""
    if isinstance(n, bool) or not isinstance(n, int) or not 1 <= n <= 3999:
        raise ValueError(f"not in range 1..3999: {n!r}")
    out = []
    for value, symbol in _NUMERALS:
        count, n = divmod(n, value)
        out.append(symbol * count)
    return "".join(out)


def from_roman(s):
    """Integer for a canonical numeral. Anything to_roman would not produce raises ValueError."""
    if not re.fullmatch(r"[IVXLCDM]+", s):
        raise ValueError(f"not a canonical Roman numeral: {s!r}")
    total = 0
    for i, ch in enumerate(s):
        value = _VALUES[ch]
        if i + 1 < len(s) and value < _VALUES[s[i + 1]]:
            total -= value
        else:
            total += value
    if to_roman(total) != s:
        raise ValueError(f"not a canonical Roman numeral: {s!r}")
    return total

